  const DRUG_IX = [{"a":"acei","b":"ksparing","sev":"mayor","mech":"Keduanya menahan kalium (hambat aldosteron/RAAS).","efek":"Hiperkalemia, dapat memicu aritmia fatal.","advice":"Pantau K+ & kreatinin 1-2 minggu setelah mulai/naik dosis. Hindari bila K+ >5,0 mmol/L atau eGFR rendah. Edukasi gejala hiperkalemia."},{"a":"arb","b":"ksparing","sev":"mayor","mech":"Keduanya menahan kalium.","efek":"Hiperkalemia.","advice":"Pantau K+ & kreatinin berkala. Hati-hati pada gagal jantung/CKD; sesuaikan dosis."},{"a":"acei","b":"ksupp","sev":"mayor","mech":"Penambahan kalium pada blokade RAAS.","efek":"Hiperkalemia.","advice":"Hindari suplemen kalium rutin kecuali ada hipokalemia terbukti; pantau K+."},{"a":"arb","b":"ksupp","sev":"mayor","mech":"Penambahan kalium pada blokade RAAS.","efek":"Hiperkalemia.","advice":"Hindari suplemen kalium kecuali terindikasi; pantau K+."},{"a":"acei","b":"arb","sev":"mayor","mech":"Blokade ganda RAAS.","efek":"Hiperkalemia, hipotensi, gangguan ginjal akut; tanpa tambahan manfaat.","advice":"Kombinasi ACEi+ARB umumnya dihindari. Pilih salah satu."},{"a":"arni","b":"acei","sev":"kontra","mech":"Sakubitril + ACEi meningkatkan bradikinin.","efek":"Risiko angioedema serius.","advice":"KONTRAINDIKASI. Beri jeda minimal 36 jam saat beralih dari ACEi ke ARNI (dan sebaliknya)."},{"a":"litium","b":"diuretik","sev":"mayor","mech":"Diuretik (tiazid) menurunkan klirens litium.","efek":"Kadar litium naik, risiko toksisitas.","advice":"Hindari tiazid bila bisa; bila perlu, pantau kadar litium ketat & sesuaikan dosis."},{"a":"litium","b":"acei","sev":"mayor","mech":"ACEi menurunkan ekskresi litium.","efek":"Toksisitas litium.","advice":"Pantau kadar litium & fungsi ginjal; turunkan dosis litium bila perlu."},{"a":"litium","b":"arb","sev":"mayor","mech":"ARB menurunkan ekskresi litium.","efek":"Toksisitas litium.","advice":"Pantau kadar litium; sesuaikan dosis."},{"a":"litium","b":"nsaid","sev":"mayor","mech":"OAINS menurunkan klirens ginjal litium.","efek":"Kadar litium naik, toksisitas.","advice":"Hindari OAINS; gunakan parasetamol. Bila terpaksa, pantau kadar litium."},{"a":"warfarin","b":"nsaid","sev":"mayor","mech":"Hambatan trombosit + iritasi mukosa + geser ikatan protein.","efek":"Risiko perdarahan (terutama GI) meningkat tajam.","advice":"Hindari OAINS. Pilih parasetamol. Bila wajib, lambung dilindungi PPI & pantau INR/tanda perdarahan."},{"a":"warfarin","b":"antiplatelet","sev":"mayor","mech":"Antikoagulan + antiplatelet.","efek":"Perdarahan mayor.","advice":"Hanya bila indikasi kuat (mis. pasca-PCI). Durasi sesingkat mungkin, tambah PPI, pantau ketat."},{"a":"warfarin","b":"makrolid","sev":"mayor","mech":"Hambatan CYP menurunkan metabolisme warfarin.","efek":"INR naik, risiko perdarahan.","advice":"Pilih antibiotik alternatif bila bisa. Pantau INR 3-5 hari setelah mulai/berhenti."},{"a":"warfarin","b":"metronidazol","sev":"mayor","mech":"Hambatan metabolisme S-warfarin.","efek":"INR naik tajam.","advice":"Hindari bila memungkinkan; bila perlu, turunkan dosis warfarin & pantau INR ketat."},{"a":"warfarin","b":"fkuinolon","sev":"sedang","mech":"Gangguan flora usus & metabolisme.","efek":"INR dapat naik.","advice":"Pantau INR selama dan setelah terapi antibiotik."},{"a":"warfarin","b":"azol","sev":"mayor","mech":"Azol menghambat CYP2C9.","efek":"INR naik, perdarahan.","advice":"Flukonazol bahkan dosis rendah berisiko. Pantau INR; sesuaikan dosis warfarin."},{"a":"warfarin","b":"inducer","sev":"sedang","mech":"Induksi enzim mempercepat metabolisme warfarin.","efek":"INR turun, risiko trombosis.","advice":"Pantau INR; sering perlu menaikkan dosis warfarin. Awasi lagi saat penginduksi dihentikan."},{"a":"warfarin","b":"kortikosteroid","sev":"sedang","mech":"Efek pada koagulasi & mukosa GI.","efek":"INR berubah + risiko ulkus/perdarahan GI.","advice":"Pantau INR; pertimbangkan proteksi lambung."},{"a":"doac","b":"nsaid","sev":"mayor","mech":"Antikoagulan + hambatan trombosit/iritasi mukosa.","efek":"Perdarahan GI.","advice":"Hindari OAINS; gunakan parasetamol. Bila perlu, tambah PPI & pantau."},{"a":"doac","b":"antiplatelet","sev":"mayor","mech":"Antikoagulan + antiplatelet.","efek":"Perdarahan mayor.","advice":"Hanya bila indikasi jelas; minimalkan durasi, pertimbangkan PPI."},{"a":"heparin","b":"nsaid","sev":"mayor","mech":"Antikoagulan parenteral + antiplatelet.","efek":"Perdarahan.","advice":"Hindari OAINS; pantau tanda perdarahan & trombosit."},{"a":"heparin","b":"antiplatelet","sev":"sedang","mech":"Antikoagulan + antiplatelet.","efek":"Perdarahan meningkat.","advice":"Lazim pada SKA tetapi awasi perdarahan; sesuaikan dosis sesuai protokol."},{"a":"antiplatelet","b":"nsaid","sev":"sedang","mech":"Iritasi mukosa + hambatan trombosit; ibuprofen dapat menghalangi efek aspirin.","efek":"Perdarahan GI; aspirin kurang efektif.","advice":"Hindari OAINS rutin. Bila aspirin + ibuprofen, beri aspirin >=2 jam sebelum ibuprofen. Pertimbangkan PPI."},{"a":"clopidogrel","b":"ppi","sev":"sedang","mech":"Omeprazol/esomeprazol menghambat CYP2C19 (aktivasi klopidogrel).","efek":"Efek antiplatelet klopidogrel menurun.","advice":"Pilih pantoprazol bila butuh PPI, atau jeda waktu pemberian."},{"a":"ssri","b":"nsaid","sev":"sedang","mech":"SSRI menurunkan agregasi trombosit + OAINS.","efek":"Risiko perdarahan GI.","advice":"Pertimbangkan PPI; pantau tanda perdarahan, terutama lansia."},{"a":"ssri","b":"warfarin","sev":"sedang","mech":"Efek pada trombosit + interaksi metabolisme.","efek":"Risiko perdarahan; INR dapat berubah.","advice":"Pantau INR & tanda perdarahan."},{"a":"statin","b":"makrolid","sev":"mayor","mech":"Klaritromisin/eritromisin menghambat CYP3A4 (simvastatin/atorvastatin).","efek":"Kadar statin naik, risiko miopati/rabdomiolisis.","advice":"Hentikan sementara simvastatin selama terapi klaritromisin/eritromisin. Azitromisin lebih aman."},{"a":"statin","b":"azol","sev":"mayor","mech":"Itrakonazol/flukonazol menghambat CYP3A4.","efek":"Miopati/rabdomiolisis.","advice":"Hindari kombinasi dengan simvastatin; jeda atau ganti statin (mis. pravastatin/rosuvastatin dosis rendah)."},{"a":"statin","b":"nondhp","sev":"sedang","mech":"Diltiazem/verapamil menghambat CYP3A4.","efek":"Kadar simvastatin naik, risiko miopati.","advice":"Batasi simvastatin <=20 mg/hari dengan diltiazem/verapamil; pantau gejala otot."},{"a":"statin","b":"siklosporin","sev":"mayor","mech":"Hambatan transport & metabolisme statin.","efek":"Miopati/rabdomiolisis.","advice":"Hindari/gunakan statin dosis sangat rendah dengan pemantauan ketat."},{"a":"statin","b":"kolkisin","sev":"sedang","mech":"Efek miotoksik aditif.","efek":"Miopati.","advice":"Pantau gejala otot & CK; hati-hati pada gangguan ginjal."},{"a":"digoksin","b":"diuretik","sev":"mayor","mech":"Diuretik menyebabkan hipokalemia/hipomagnesemia.","efek":"Sensitisasi miokardium, toksisitas digoksin.","advice":"Pantau K+/Mg2+ & kadar digoksin; koreksi elektrolit."},{"a":"digoksin","b":"amiodaron","sev":"mayor","mech":"Amiodaron menaikkan kadar digoksin.","efek":"Toksisitas digoksin.","advice":"Turunkan dosis digoksin ~50% dan pantau kadar."},{"a":"digoksin","b":"nondhp","sev":"mayor","mech":"Verapamil/diltiazem menaikkan digoksin + efek pada nodus AV.","efek":"Toksisitas digoksin, bradikardia/blok AV.","advice":"Pantau kadar digoksin & EKG; sesuaikan dosis."},{"a":"digoksin","b":"ksparing","sev":"sedang","mech":"Spironolakton menaikkan kadar digoksin.","efek":"Toksisitas digoksin.","advice":"Pantau kadar digoksin; awasi tanda toksisitas."},{"a":"bblocker","b":"nondhp","sev":"mayor","mech":"Penekanan nodus SA/AV & inotropik negatif aditif.","efek":"Bradikardia berat, blok AV, gagal jantung.","advice":"Hindari kombinasi verapamil/diltiazem + beta-blocker, terutama IV. Bila perlu, pantau EKG & hemodinamik."},{"a":"qt","b":"qt","self":true,"sev":"mayor","mech":"Pemanjangan interval QT aditif.","efek":"Risiko Torsades de Pointes.","advice":"Hindari kombinasi bila bisa. Bila perlu: EKG (QTc), koreksi K+/Mg2+, hindari pada QTc panjang/bradikardia."},{"a":"ssri","b":"tramadol","sev":"mayor","mech":"Efek serotonergik aditif + tramadol menurunkan ambang kejang.","efek":"Sindrom serotonin, risiko kejang.","advice":"Hindari bila bisa. Bila perlu, dosis minimal & awasi gejala (agitasi, klonus, hipertermia)."},{"a":"ssri","b":"linezolid","sev":"kontra","mech":"Linezolid bersifat MAOI lemah.","efek":"Sindrom serotonin.","advice":"Hindari. Bila linezolid mendesak, hentikan SSRI & beri jeda washout sesuai pedoman; awasi ketat."},{"a":"tramadol","b":"linezolid","sev":"mayor","mech":"Efek serotonergik + MAOI.","efek":"Sindrom serotonin, kejang.","advice":"Hindari kombinasi; pilih analgesik/antibiotik alternatif."},{"a":"teofilin","b":"fkuinolon","sev":"mayor","mech":"Siprofloksasin menghambat metabolisme teofilin.","efek":"Toksisitas teofilin (aritmia, kejang).","advice":"Hindari siprofloksasin; pantau kadar teofilin bila terpaksa."},{"a":"teofilin","b":"makrolid","sev":"sedang","mech":"Hambatan metabolisme teofilin.","efek":"Kadar teofilin naik.","advice":"Pantau kadar & gejala toksisitas."},{"a":"nitrat","b":"pde5","sev":"kontra","mech":"Vasodilatasi via NO/cGMP yang berlebihan.","efek":"Hipotensi berat, sinkop.","advice":"KONTRAINDIKASI. Jangan beri nitrat dalam 24 jam (sildenafil) hingga 48 jam (tadalafil) setelah PDE5."},{"a":"inducer","b":"coc","sev":"mayor","mech":"Induksi enzim mempercepat metabolisme hormon.","efek":"Kegagalan kontrasepsi.","advice":"Gunakan metode tambahan/alternatif (mis. AKDR) selama & 4 minggu setelah penginduksi."},{"a":"inducer","b":"kortikosteroid","sev":"sedang","mech":"Induksi enzim menurunkan kadar steroid.","efek":"Efek steroid berkurang.","advice":"Mungkin perlu naikkan dosis steroid; pantau respons klinis."},{"a":"valproat","b":"lamotrigin","sev":"mayor","mech":"Valproat menghambat metabolisme lamotrigin.","efek":"Kadar lamotrigin naik, risiko ruam berat (SJS).","advice":"Titrasi lamotrigin sangat lambat & dosis lebih rendah saat dengan valproat."},{"a":"metotreksat","b":"nsaid","sev":"mayor","mech":"OAINS menurunkan ekskresi MTX (terutama dosis tinggi).","efek":"Toksisitas MTX (sumsum tulang, ginjal).","advice":"Hindari pada MTX dosis tinggi. Pada dosis rendah reumatologi, pantau hitung darah & fungsi ginjal."},{"a":"levotiroksin","b":"pengikat","sev":"sedang","mech":"Antasida/kalsium/sukralfat mengikat levotiroksin di usus.","efek":"Absorpsi levotiroksin turun, hipotiroid.","advice":"Beri jarak minimal 4 jam antara levotiroksin dan pengikat."},{"a":"fkuinolon","b":"pengikat","sev":"sedang","mech":"Kelasi dengan kation polivalen (Ca/Mg/Al).","efek":"Absorpsi antibiotik turun, gagal terapi.","advice":"Beri kuinolon 2 jam sebelum atau 6 jam sesudah antasida/kalsium."},{"a":"sulfonilurea","b":"bblocker","sev":"sedang","mech":"Beta-blocker (non-selektif) menutupi gejala adrenergik hipoglikemia.","efek":"Hipoglikemia tak terdeteksi & berkepanjangan.","advice":"Pilih beta-blocker selektif; edukasi tanda hipoglikemia non-adrenergik (berkeringat tetap ada)."},{"a":"insulin","b":"bblocker","sev":"sedang","mech":"Beta-blocker menutupi gejala hipoglikemia.","efek":"Hipoglikemia tersamar.","advice":"Pilih beta-blocker selektif; pantau gula & edukasi pasien."},{"a":"kortikosteroid","b":"nsaid","sev":"sedang","mech":"Efek aditif pada mukosa lambung.","efek":"Tukak & perdarahan GI.","advice":"Hindari kombinasi rutin; bila perlu, tambahkan PPI & pantau gejala GI."},{"a":"opioid","b":"benzodiazepin","sev":"mayor","mech":"Depresi sistem saraf pusat aditif pada pusat napas batang otak.","efek":"Sedasi dalam, depresi napas, hipoksia, sampai henti napas dan kematian.","advice":"Hindari bila ada alternatif. Bila terpaksa (misal nyeri kanker dengan ansietas berat), mulai dari dosis serendah mungkin, turunkan dosis salah satu 30-50%, pantau laju napas dan SpO2 tiap 1-2 jam pada 24 jam pertama, sediakan nalokson, edukasi keluarga tanda depresi napas."},{"a":"opioid","b":"gabapentinoid","sev":"mayor","mech":"Depresi SSP aditif; gabapentinoid juga meningkatkan kadar puncak opioid oral.","efek":"Sedasi berlebihan dan depresi napas, risiko tertinggi pada lansia, gangguan ginjal, dan PPOK.","advice":"Mulai pregabalin 25-75 mg/hari atau gabapentin 100-300 mg/hari lalu titrasi lambat, sesuaikan dosis pada eGFR < 60, pantau kesadaran dan laju napas 3-5 hari pertama serta setiap kenaikan dosis."},{"a":"opioid","b":"antihistamin-sedatif","sev":"sedang","mech":"Efek sedatif dan antikolinergik aditif.","efek":"Mengantuk, delirium pada lansia, konstipasi berat sampai ileus, retensi urin.","advice":"Pada lansia pilih antihistamin non-sedatif (setirizin, loratadin, feksofenadin) atau hentikan antihistamin. Bila tetap dipakai, hindari mengemudi, nilai kesadaran dan pola defekasi tiap kunjungan, mulai laksatif profilaksis."},{"a":"opioid","b":"linezolid","sev":"mayor","mech":"Linezolid adalah penghambat MAO lemah, sedangkan petidin, fentanil, tramadol, dan tapentadol bersifat serotonergik.","efek":"Sindrom serotonin: agitasi, klonus, hiperrefleksi, hipertermia, takikardia.","advice":"Jangan gabungkan petidin, tramadol, atau tapentadol dengan linezolid. Bila butuh opioid selama terapi linezolid, gunakan morfin atau kodein. Bila kombinasi tak terhindarkan, pantau suhu, klonus, dan tekanan darah tiap 8 jam selama 14 hari terapi."},{"a":"benzodiazepin","b":"azol","sev":"sedang","mech":"Penghambatan CYP3A4 oleh flukonazol, itrakonazol, dan mikonazol gel oral menurunkan bersihan midazolam dan alprazolam.","efek":"Sedasi memanjang, amnesia, gangguan keseimbangan dan jatuh.","advice":"Turunkan dosis midazolam 50-75% bila dipakai untuk sedasi prosedural pada pasien yang mendapat azol; untuk alprazolam turunkan dosis atau ganti lorazepam yang tidak lewat CYP3A4. Pantau kesadaran sampai 24 jam pascaprosedur."},{"a":"ssri","b":"triptan","sev":"sedang","mech":"Stimulasi serotonergik aditif di sistem saraf pusat.","efek":"Risiko sindrom serotonin, umumnya ringan tetapi bisa berat pada dosis triptan berulang.","advice":"Kombinasi boleh dengan pengawasan. Batasi sumatriptan maksimal 2 dosis per hari, edukasi pasien mengenali agitasi, tremor, diare, dan demam; hentikan triptan dan cari pertolongan bila muncul. Waspada khusus bila ISRS baru dimulai atau dosis baru dinaikkan."},{"a":"ssri","b":"tca","sev":"mayor","mech":"Fluoksetin dan paroksetin menghambat CYP2D6 sehingga kadar amitriptilin melonjak, ditambah efek serotonergik aditif.","efek":"Toksisitas trisiklik: kardiotoksik dengan pelebaran QRS dan QT, delirium antikolinergik, kejang, sindrom serotonin.","advice":"Hindari kombinasi rutin. Bila amitriptilin dosis rendah untuk nyeri neuropatik tetap diperlukan, mulai 10 mg malam, jangan melebihi 25 mg, rekam EKG awal dan setelah 2 minggu, hentikan bila QRS > 100 ms."},{"a":"ssri","b":"litium","sev":"mayor","mech":"Efek serotonergik aditif dan peningkatan kadar litium pada sebagian pasien.","efek":"Sindrom serotonin serta neurotoksisitas litium: tremor kasar, ataksia, bingung, mioklonus.","advice":"Boleh dikombinasi pada gangguan bipolar dengan pemantauan ketat. Periksa kadar litium sebelum, 5-7 hari sesudah memulai atau menaikkan dosis ISRS, lalu tiap 3 bulan; target 0,6-0,8 mmol/L. Hentikan segera bila muncul tremor kasar, ataksia, atau demam."},{"a":"ssri","b":"antiplatelet","sev":"sedang","mech":"ISRS mendeplesi serotonin trombosit sehingga agregasi terganggu, aditif dengan hambatan COX-1 atau P2Y12.","efek":"Peningkatan perdarahan saluran cerna atas, memar, dan perdarahan pascaoperasi.","advice":"Nilai risiko perdarahan; tambahkan PPI bila usia > 60 tahun, ada riwayat ulkus, atau terapi ganda antiplatelet. Pantau Hb tiap 3 bulan dan tanya keluhan melena tiap kunjungan. Pertimbangkan mirtazapin bila risiko perdarahan tinggi."},{"a":"ssri","b":"doac","sev":"sedang","mech":"Gangguan fungsi trombosit oleh ISRS ditambah antikoagulasi.","efek":"Peningkatan risiko perdarahan mayor, terutama saluran cerna dan intrakranial.","advice":"Gunakan dosis DOAC sesuai fungsi ginjal dan usia, tambahkan PPI bila ada faktor risiko saluran cerna. Periksa Hb dan kreatinin tiap 3-6 bulan, hindari penambahan OAINS. Edukasi laporkan tinja hitam atau nyeri kepala mendadak."},{"a":"tca","b":"linezolid","sev":"mayor","mech":"Hambatan MAO oleh linezolid pada pasien yang memakai penghambat ambilan kembali serotonin dan noradrenalin.","efek":"Sindrom serotonin dan krisis hipertensi.","advice":"Hentikan amitriptilin bila memungkinkan sebelum memulai linezolid, atau pilih antibiotik lain (vankomisin, klindamisin) sesuai kepekaan. Bila keduanya tidak dapat dihindari, pantau tekanan darah, suhu, dan klonus tiap 8 jam."},{"a":"triptan","b":"ergot","sev":"kontra","mech":"Vasokonstriksi aditif melalui reseptor 5-HT1B pada arteri koroner dan perifer.","efek":"Iskemia miokard, spasme arteri perifer, hipertensi berat.","advice":"Jangan diberikan bersama. Beri jarak minimal 24 jam antara ergotamin dan sumatriptan (dan sebaliknya). Untuk migrain akut pilih salah satu saja, tambahkan OAINS atau antiemetik bila respons kurang."},{"a":"ergot","b":"makrolid","sev":"kontra","mech":"Eritromisin dan klaritromisin menghambat kuat CYP3A4 yang memetabolisme alkaloid ergot.","efek":"Ergotisme: vasospasme berat, akral dingin dan nyeri, iskemia ekstremitas sampai gangren.","advice":"Jangan gabungkan. Ganti ke azitromisin (interaksi CYP3A4 minimal) atau antibiotik golongan lain, atau hentikan ergotamin selama terapi makrolid dan alihkan ke parasetamol, OAINS, atau triptan."},{"a":"ergot","b":"azol","sev":"kontra","mech":"Itrakonazol dan flukonazol menghambat CYP3A4 sehingga kadar ergot meningkat tajam.","efek":"Ergotisme dengan iskemia ekstremitas dan vasospasme serebral.","advice":"Jangan gabungkan. Hentikan ergotamin selama terapi azol, gunakan terbinafin untuk infeksi jamur kuku atau kulit bila sesuai, dan pakai analgesik non-ergot untuk migrain."},{"a":"xantin-oksidase","b":"azatioprin","sev":"kontra","mech":"Alopurinol dan febuxostat menghambat xantin oksidase, jalur utama pemecahan 6-merkaptopurin hasil metabolisme azatioprin.","efek":"Akumulasi metabolit sitotoksik, mielosupresi berat, pansitopenia, sepsis neutropenik.","advice":"Febuxostat: jangan dikombinasi. Alopurinol: hindari; bila benar-benar tak ada pilihan, turunkan azatioprin menjadi 25% dosis awal dan periksa darah lengkap tiap minggu selama 1 bulan lalu tiap bulan. Untuk gout pada pasien azatioprin, gunakan kolkisin dosis rendah atau steroid."},{"a":"karbapenem","b":"valproat","sev":"mayor","mech":"Meropenem menghambat hidrolisis valproat-glukuronida dan menurunkan absorpsinya, sehingga kadar valproat anjlok.","efek":"Kadar valproat turun sampai 60-100% dalam 24-48 jam dan memicu kejang lepas kendali; menaikkan dosis valproat tidak efektif.","advice":"Hindari kombinasi. Ganti antibiotik ke seftriakson, sefepim, atau piperasilin-tazobaktam sesuai kepekaan. Bila meropenem wajib, ganti antiepileptik ke levetirasetam atau fenitoin dan periksa kadar valproat 48 jam setelah meropenem dihentikan."},{"a":"aminoglikosida","b":"loop","sev":"mayor","mech":"Toksisitas aditif pada sel rambut koklea dan tubulus proksimal ginjal, diperberat deplesi volume oleh diuretik.","efek":"Tuli sensorineural yang sering menetap, tinitus, vertigo, dan gagal ginjal akut.","advice":"Hindari bila memungkinkan. Bila perlu, jangan berikan dalam waktu bersamaan (beri jarak beberapa jam), pertahankan euvolemia, periksa kreatinin dan urin output tiap hari, batasi terapi maksimal 7 hari, dan tanyakan tinitus atau penurunan pendengaran setiap hari."},{"a":"aminoglikosida","b":"vankomisin","sev":"mayor","mech":"Nefrotoksisitas tubular aditif.","efek":"Gagal ginjal akut, kadang disertai ototoksisitas; risiko meningkat pada terapi lebih dari 7 hari dan pada lansia.","advice":"Gabungkan hanya bila ada indikasi sinergi (endokarditis enterokokus, sepsis berat) dan sesingkat mungkin. Periksa kreatinin setiap hari, target kadar palung vankomisin 10-15 mg/L (atau AUC 400-600), sesuaikan dosis aminoglikosida menurut eGFR, hentikan aminoglikosida begitu kultur memungkinkan."},{"a":"aminoglikosida","b":"siklosporin","sev":"mayor","mech":"Vasokonstriksi ginjal oleh siklosporin ditambah toksisitas tubular langsung aminoglikosida.","efek":"Gagal ginjal akut dan kehilangan fungsi cangkok.","advice":"Pilih antibiotik alternatif (sefalosporin, karbapenem). Bila terpaksa, periksa kreatinin dan kadar siklosporin tiap 2-3 hari, pertahankan hidrasi, hindari OAINS dan kontras iodin bersamaan."},{"a":"aminoglikosida","b":"pelemas-otot","sev":"mayor","mech":"Aminoglikosida menghambat pelepasan asetilkolin prasinaps dan memperkuat blokade neuromuskular nondepolarisasi.","efek":"Blokade memanjang, kegagalan ekstubasi, kelemahan otot napas pascaoperasi; dapat mencetuskan krisis miastenia.","advice":"Hindari aminoglikosida pada miastenia gravis. Di kamar bedah, kurangi dosis rokuronium, gunakan pemantauan train-of-four, siapkan sugammadeks atau neostigmin, dan jangan ekstubasi sebelum kekuatan otot pulih penuh."},{"a":"magnesium-iv","b":"pelemas-otot","sev":"mayor","mech":"Magnesium menghambat masuknya kalsium ke ujung saraf motorik dan memperkuat blokade neuromuskular.","efek":"Blokade memanjang, apnea pascaoperasi, kelemahan otot napas; relevan pada seksio sesarea dengan preeklampsia.","advice":"Turunkan dosis rokuronium sekitar 25-50% pada pasien yang mendapat MgSO4, gunakan train-of-four, siapkan sugammadeks. Pantau refleks patela, laju napas (jaga di atas 12 per menit), dan produksi urin (di atas 0,5 mL/kg/jam); siapkan kalsium glukonas sebagai antidot."},{"a":"magnesium-iv","b":"ccb-dhp","sev":"sedang","mech":"Hambatan kanal kalsium aditif pada otot polos vaskular dan neuromuskular.","efek":"Hipotensi ibu, blok neuromuskular, dan jarang edema paru pada tokolisis.","advice":"Kombinasi MgSO4 dan nifedipin pada preeklampsia atau tokolisis boleh dilakukan namun ukur tekanan darah tiap 15 menit pada jam pertama setelah dosis nifedipin, pertahankan tekanan sistolik di atas 90 mmHg, pantau refleks patela dan laju napas, hindari nifedipin sublingual."},{"a":"metronidazol","b":"litium","sev":"mayor","mech":"Metronidazol menurunkan bersihan litium di ginjal.","efek":"Kadar litium naik sampai kadar toksik: tremor kasar, ataksia, muntah, bingung, aritmia.","advice":"Pilih antibiotik lain bila memungkinkan. Bila metronidazol wajib, periksa kadar litium sebelum dan pada hari ke-3 terapi, pertahankan asupan cairan dan garam stabil, hentikan litium bila kadar melebihi 1,2 mmol/L atau muncul gejala neurologis."},{"a":"karbamazepin","b":"makrolid","sev":"mayor","mech":"Eritromisin dan klaritromisin menghambat CYP3A4, jalur utama metabolisme karbamazepin.","efek":"Kadar karbamazepin dapat naik dua kali lipat dalam beberapa hari: pusing berputar, diplopia, ataksia, mual, hiponatremia, sampai penurunan kesadaran.","advice":"Ganti ke azitromisin atau antibiotik non-makrolid. Bila tidak mungkin, turunkan dosis karbamazepin 30-50% sejak hari pertama, periksa kadar karbamazepin pada hari ke-3 (target 4-12 mcg/mL), dan kembalikan dosis setelah makrolid selesai."},{"a":"karbamazepin","b":"azol","sev":"mayor","mech":"Hambatan CYP3A4 oleh itrakonazol, flukonazol, dan mikonazol; sebaliknya karbamazepin menginduksi metabolisme azol.","efek":"Toksisitas karbamazepin (ataksia, diplopia, mengantuk) sekaligus kegagalan terapi antijamur.","advice":"Hindari itrakonazol pada pengguna karbamazepin; pilih terbinafin untuk infeksi dermatofita. Bila azol wajib, turunkan karbamazepin 30-50%, periksa kadar pada hari ke-3 dan ke-7, dan nilai ulang respons antijamur setelah 2 minggu."},{"a":"karbamazepin","b":"valproat","sev":"sedang","mech":"Karbamazepin menginduksi metabolisme valproat, sedangkan valproat menghambat epoksida hidrolase sehingga metabolit aktif karbamazepin-10,11-epoksida menumpuk.","efek":"Kadar valproat turun sementara gejala toksik karbamazepin muncul walau kadar total tampak normal: mengantuk, pusing, mual, ataksia.","advice":"Kombinasi boleh untuk epilepsi refrakter. Periksa kadar keduanya 1-2 minggu setelah perubahan dosis, nilai gejala klinis (bukan hanya kadar), dan naikkan dosis secara bertahap. Periksa amonia bila muncul letargi."},{"a":"isoniazid","b":"fenitoin","sev":"mayor","mech":"Isoniazid menghambat CYP2C19 dan CYP2C9 sehingga metabolisme fenitoin terhambat, terutama pada asetilator lambat.","efek":"Intoksikasi fenitoin: nistagmus, ataksia, bicara pelo, bingung; dapat muncul dalam 1-2 minggu.","advice":"Periksa kadar fenitoin sebelum memulai OAT, lalu pada hari ke-7 dan ke-14 (target 10-20 mcg/mL atau bebas 1-2 mcg/mL). Turunkan dosis fenitoin bila muncul nistagmus. Ingat rifampisin dalam paduan OAT bekerja berlawanan, jadi kadar harus benar-benar dipantau, bukan diperkirakan."},{"a":"isoniazid","b":"karbamazepin","sev":"mayor","mech":"Isoniazid menghambat CYP3A4 sehingga kadar karbamazepin naik; kombinasi juga menambah risiko hepatotoksik.","efek":"Toksisitas karbamazepin (ataksia, diplopia, mengantuk) dan peningkatan transaminase sampai hepatitis.","advice":"Periksa kadar karbamazepin dan SGPT sebelum OAT, lalu tiap 2 minggu pada bulan pertama. Turunkan karbamazepin bila ada gejala. Hentikan OAT bila SGPT lebih dari 3 kali batas atas disertai gejala atau lebih dari 5 kali tanpa gejala."},{"a":"fenitoin","b":"valproat","sev":"mayor","mech":"Valproat menggeser fenitoin dari ikatan albumin sekaligus menghambat metabolismenya.","efek":"Fraksi bebas fenitoin meningkat sehingga muncul tanda intoksikasi meski kadar total terlihat normal atau rendah.","advice":"Jangan menaikkan dosis fenitoin hanya berdasar kadar total. Periksa kadar fenitoin bebas bila tersedia (target 1-2 mcg/mL) atau nilai klinis: nistagmus, ataksia, bicara pelo. Sesuaikan dosis atas dasar gejala dan periksa albumin."},{"a":"fenitoin","b":"simetidin","sev":"sedang","mech":"Simetidin menghambat CYP2C9 dan CYP2C19.","efek":"Kadar fenitoin naik dan memicu nistagmus, ataksia, serta mengantuk dalam 1-2 minggu.","advice":"Ganti simetidin dengan famotidin atau PPI yang tidak menghambat enzim ini secara bermakna. Bila simetidin dipertahankan, periksa kadar fenitoin setelah 7 hari dan turunkan dosis bila ada gejala."},{"a":"lamotrigin","b":"coc","sev":"mayor","mech":"Etinilestradiol menginduksi glukuronidasi lamotrigin.","efek":"Kadar lamotrigin turun sekitar 50% saat pil aktif diminum sehingga kejang kambuh, lalu melonjak pada minggu bebas pil dan menimbulkan pusing serta diplopia.","advice":"Bila pil kombinasi dimulai, dosis lamotrigin umumnya perlu dinaikkan sampai dua kali lipat secara bertahap dengan pemantauan kadar. Bila pil dihentikan, turunkan lamotrigin kembali. Pilih kontrasepsi tanpa estrogen (progestin saja, AKDR) untuk menghindari fluktuasi."},{"a":"lamotrigin","b":"inducer","sev":"sedang","mech":"Karbamazepin, fenitoin, fenobarbital, dan rifampisin mempercepat glukuronidasi lamotrigin.","efek":"Kadar lamotrigin turun sampai separuh sehingga kendali kejang atau stabilisasi mood hilang.","advice":"Gunakan skema titrasi lamotrigin untuk pasien yang memakai penginduksi (dosis rumatan biasanya lebih tinggi, sekitar 200-400 mg/hari terbagi dua). Turunkan dosis bertahap bila penginduksi dihentikan dan pantau munculnya ruam serta pusing."},{"a":"rifampisin","b":"arv","sev":"mayor","mech":"Rifampisin adalah penginduksi kuat CYP3A4 dan UGT1A1 sehingga kadar dolutegravir dan efavirenz turun.","efek":"Kadar antiretroviral subterapi, kegagalan virologis, dan timbulnya resistensi.","advice":"Jangan hentikan OAT; sesuaikan ARV. Dolutegravir dinaikkan menjadi 50 mg dua kali sehari selama terapi rifampisin dan 2 minggu sesudahnya. Jangan gabungkan rifampisin dengan rejimen berbasis penghambat protease. Periksa viral load 3 bulan setelah penyesuaian."},{"a":"arv","b":"pengikat","sev":"sedang","mech":"Dolutegravir membentuk kelat dengan kation polivalen (aluminium, magnesium, kalsium, zink) dalam antasida dan suplemen.","efek":"Absorpsi dolutegravir turun tajam sehingga kadar subterapi dan risiko resistensi.","advice":"Minum dolutegravir 2 jam sebelum atau 6 jam sesudah antasida, sukralfat, atau suplemen kalsium/zink. Bila suplemen dikonsumsi bersama makanan, dolutegravir boleh diminum bersamaan dengan makanan tersebut. Periksa viral load bila kepatuhan jadwal diragukan."},{"a":"arv","b":"metformin","sev":"sedang","mech":"Dolutegravir menghambat transporter OCT2 dan MATE1 di ginjal sehingga sekresi metformin berkurang.","efek":"Kadar metformin naik sekitar dua kali lipat, menambah keluhan saluran cerna dan risiko asidosis laktat.","advice":"Batasi metformin maksimal 1000 mg/hari saat memulai dolutegravir, mulai dari 500 mg. Pantau gula darah, keluhan mual atau diare, dan kreatinin tiap 3 bulan. Hentikan metformin sementara pada dehidrasi atau sepsis."},{"a":"antipsikotik","b":"antidopaminergik","sev":"mayor","mech":"Blokade reseptor D2 di ganglia basalis yang aditif dari dua sumber.","efek":"Gejala ekstrapiramidal akut (distonia, akatisia, parkinsonisme), diskinesia tardif, dan sindrom neuroleptik maligna.","advice":"Hindari metoklopramid pada pasien antipsikotik; pilih ondansetron untuk mual atau domperidon jangka pendek. Batasi metoklopramid maksimal 5 hari dan 30 mg/hari. Bila muncul kekakuan, demam, dan CK meningkat, hentikan keduanya dan tangani sebagai sindrom neuroleptik maligna."},{"a":"antipsikotik","b":"litium","sev":"mayor","mech":"Neurotoksisitas aditif, terutama dengan haloperidol dosis tinggi.","efek":"Sindrom ensefalopati: bingung, kekakuan, demam, tremor kasar, leukositosis, kadang berlanjut menjadi kerusakan serebelar menetap.","advice":"Kombinasi lazim pada mania akut tetapi jaga kadar litium 0,6-0,8 mmol/L, gunakan dosis haloperidol serendah mungkin (biasanya di bawah 10 mg/hari), periksa kadar litium tiap minggu pada fase akut, dan hentikan segera bila muncul kekakuan atau demam."},{"a":"antikolinergik","b":"antihistamin-sedatif","sev":"sedang","mech":"Beban antikolinergik aditif pada reseptor muskarinik sentral dan perifer.","efek":"Delirium pada lansia, mulut kering, konstipasi, retensi urin, penglihatan kabur, glaukoma sudut tertutup akut, dan risiko jatuh.","advice":"Hitung beban antikolinergik dan hentikan yang tidak esensial. Pada lansia, ganti antihistamin sedatif dengan loratadin atau setirizin dan hindari kombinasi dengan oksibutinin atau triheksifenidil. Pantau status mental, residu urin, dan pola defekasi tiap kunjungan."},{"a":"antikolinergik","b":"kolinergik","sev":"sedang","mech":"Antagonisme farmakodinamik langsung pada reseptor muskarinik.","efek":"Manfaat donepezil pada demensia hilang, sekaligus muncul efek antikolinergik seperti bingung dan retensi urin; contoh khas kaskade peresepan donepezil lalu oksibutinin.","advice":"Hindari kombinasi. Untuk kandung kemih overaktif pada pasien donepezil, coba latihan berkemih terjadwal atau mirabegron bila tersedia. Bila terpaksa, nilai ulang fungsi kognitif (misal MMSE) setelah 4-8 minggu dan hentikan bila memburuk."},{"a":"teofilin","b":"simetidin","sev":"mayor","mech":"Simetidin menghambat CYP1A2 sehingga bersihan teofilin turun sekitar 30-40%.","efek":"Toksisitas teofilin: mual, muntah, takikardia, tremor, aritmia, dan kejang; rentang terapinya sempit.","advice":"Ganti simetidin dengan famotidin atau PPI. Bila tidak mungkin, turunkan dosis teofilin sekitar sepertiga sejak awal, periksa kadar teofilin setelah 2-3 hari (target 10-20 mcg/mL), dan hentikan bila muncul muntah atau takiaritmia."},{"a":"teofilin","b":"bblocker","sev":"mayor","mech":"Antagonisme farmakodinamik pada reseptor beta-2 bronkus; penyekat beta nonselektif seperti propranolol paling berbahaya.","efek":"Bronkospasme berat pada asma dan PPOK, sekaligus hilangnya efek bronkodilator teofilin dan salbutamol.","advice":"Jangan berikan propranolol, karvedilol, atau timolol tetes mata pada pasien asma yang memakai teofilin. Bila penyekat beta wajib (pascainfark, gagal jantung), pilih bisoprolol atau metoprolol dosis rendah, mulai titrasi lambat, dan pantau APE serta mengi pada minggu pertama."},{"a":"metformin","b":"simetidin","sev":"sedang","mech":"Simetidin menghambat sekresi tubular metformin melalui OCT2.","efek":"Kadar metformin naik sekitar 40-60% sehingga keluhan saluran cerna bertambah dan risiko asidosis laktat meningkat pada gangguan ginjal.","advice":"Gunakan famotidin atau PPI sebagai pengganti. Bila simetidin tetap dipakai, turunkan metformin (misal maksimal 1000 mg/hari), periksa eGFR, dan hentikan metformin bila eGFR di bawah 30 mL/menit/1,73 m2."},{"a":"ppi","b":"besi","sev":"sedang","mech":"Penekanan asam lambung mengurangi perubahan besi feri menjadi fero yang dapat diserap.","efek":"Respons terapi besi oral melambat atau gagal, anemia defisiensi besi tidak membaik.","advice":"Minum sulfas ferosus saat perut kosong bersama vitamin C 250-500 mg atau air jeruk, dan hentikan PPI bila indikasinya tidak kuat. Periksa Hb dan feritin setelah 4 minggu; bila Hb naik kurang dari 1 g/dL, pertimbangkan besi intravena."},{"a":"ppi","b":"azol","sev":"sedang","mech":"Itrakonazol kapsul butuh suasana asam untuk larut dan diserap; PPI menaikkan pH lambung.","efek":"Kadar itrakonazol turun tajam sehingga terapi jamur gagal.","advice":"Minum itrakonazol kapsul bersama makanan dan minuman bersoda atau asam. Bila PPI tidak dapat dihentikan, ganti ke flukonazol atau terbinafin yang penyerapannya tidak bergantung asam. Nilai respons klinis setelah 2-4 minggu."},{"a":"metotreksat","b":"ppi","sev":"sedang","mech":"PPI menghambat transporter BCRP dan sekresi tubular metotreksat di ginjal.","efek":"Kadar metotreksat dan metabolitnya bertahan lebih lama sehingga muncul mielosupresi, stomatitis, dan gangguan hati.","advice":"Relevan terutama pada dosis mingguan sedang sampai tinggi. Hentikan PPI 2-3 hari sebelum dan sesudah dosis metotreksat atau ganti famotidin. Periksa darah lengkap, SGPT, dan kreatinin tiap 2-4 minggu pada awal terapi."},{"a":"metotreksat","b":"kotrimoksazol","sev":"kontra","mech":"Trimetoprim adalah antifolat kedua dan sulfametoksazol menggeser metotreksat dari albumin serta menghambat sekresi tubularnya.","efek":"Mielosupresi berat, pansitopenia, mukositis, dan kematian; dilaporkan bahkan pada metotreksat dosis rendah mingguan.","advice":"Jangan dikombinasi. Pilih antibiotik lain untuk ISK atau infeksi kulit (nitrofurantoin, sefaleksin, amoksisilin-klavulanat). Bila terpapar, periksa darah lengkap segera, beri asam folinat, dan rawat bila neutrofil turun."},{"a":"metotreksat","b":"probenesid","sev":"mayor","mech":"Probenesid menghambat sekresi metotreksat di tubulus ginjal.","efek":"Kadar metotreksat naik beberapa kali lipat sehingga terjadi mielosupresi, mukositis, dan gangguan ginjal.","advice":"Hindari kombinasi. Untuk gout pada pasien metotreksat, gunakan alopurinol atau kolkisin dosis rendah. Bila terpaksa, kurangi dosis metotreksat dan periksa darah lengkap tiap minggu selama 1 bulan."},{"a":"metotreksat","b":"salisilat","sev":"mayor","mech":"Asetosal menggeser metotreksat dari ikatan protein dan menekan sekresi tubularnya.","efek":"Kadar metotreksat bebas naik sehingga muncul mielosupresi, stomatitis, dan toksisitas hati.","advice":"Asetosal 80 mg/hari untuk profilaksis kardiovaskular umumnya masih dapat dilanjutkan dengan pemantauan; hindari asetosal dosis analgesik atau antiinflamasi. Periksa darah lengkap, SGPT, dan kreatinin tiap 4-8 minggu, dan pastikan suplementasi asam folat 5 mg/minggu."},{"a":"levotiroksin","b":"besi","sev":"sedang","mech":"Besi membentuk kompleks tak larut dengan levotiroksin di lumen usus.","efek":"Absorpsi levotiroksin turun sehingga TSH kembali naik dan gejala hipotiroid muncul lagi.","advice":"Beri jarak minimal 4 jam: levotiroksin pagi saat perut kosong, sulfas ferosus siang atau malam. Periksa TSH 6-8 minggu setelah suplementasi besi dimulai atau dihentikan dan sesuaikan dosis levotiroksin bila perlu."},{"a":"levotiroksin","b":"ppi","sev":"sedang","mech":"Penurunan keasaman lambung mengganggu pelarutan dan penyerapan levotiroksin tablet.","efek":"TSH naik dan gejala hipotiroid muncul kembali walau dosis tidak berubah.","advice":"Pertahankan jadwal tetap: levotiroksin 30-60 menit sebelum sarapan, PPI pada waktu berbeda. Periksa TSH 6-8 minggu setelah PPI dimulai atau dihentikan; kenaikan kebutuhan dosis sekitar 10-30% sering diperlukan."},{"a":"levotiroksin","b":"warfarin","sev":"mayor","mech":"Hormon tiroid mempercepat katabolisme faktor pembekuan yang bergantung vitamin K.","efek":"Efek warfarin menguat saat levotiroksin dimulai atau dosisnya dinaikkan sehingga INR melonjak dan terjadi perdarahan; sebaliknya INR turun bila levotiroksin dihentikan.","advice":"Periksa INR 5-7 hari setelah setiap perubahan dosis levotiroksin, lalu tiap minggu sampai stabil dua kali berturut-turut. Antisipasi penurunan dosis warfarin sekitar 20-25% saat status tiroid berubah dari hipotiroid menjadi eutiroid."},{"a":"bifosfonat","b":"pengikat","sev":"sedang","mech":"Kation polivalen dalam antasida, sukralfat, dan sediaan kalsium mengikat bifosfonat di saluran cerna.","efek":"Bioavailabilitas alendronat yang memang hanya sekitar 0,6% menjadi hampir nol sehingga terapi osteoporosis gagal.","advice":"Minum alendronat pagi hari dengan air putih biasa, tetap tegak 30 menit, dan tunda antasida, sukralfat, atau kalsium minimal 30-60 menit sesudahnya. Nilai kepatuhan dan densitas tulang setelah 12-24 bulan."},{"a":"bifosfonat","b":"nsaid","sev":"sedang","mech":"Iritasi mukosa langsung oleh bifosfonat oral ditambah hambatan prostaglandin pelindung oleh OAINS.","efek":"Esofagitis, ulkus esofagus dan lambung, serta perdarahan saluran cerna atas.","advice":"Pastikan alendronat diminum dengan segelas penuh air dan pasien tidak berbaring 30 menit. Bila OAINS harus dipakai lama, tambahkan PPI, pertimbangkan asam zoledronat intravena, dan hentikan bifosfonat oral bila muncul nyeri retrosternal atau disfagia."},{"a":"tetrasiklin","b":"besi","sev":"sedang","mech":"Pembentukan kelat antara besi dan cincin tetrasiklin di lumen usus.","efek":"Absorpsi doksisiklin dan tetrasiklin turun sampai lebih dari separuh sehingga terapi infeksi gagal.","advice":"Beri jarak minimal 2 jam sebelum atau 4 jam sesudah preparat besi. Bila jadwal sulit diatur selama terapi antibiotik singkat, hentikan sementara suplemen besi dan lanjutkan setelah antibiotik selesai."},{"a":"tetrasiklin","b":"pengikat","sev":"sedang","mech":"Kelat dengan kalsium, magnesium, aluminium, dan zink dalam antasida serta suplemen.","efek":"Kadar antibiotik subterapi dan kegagalan pengobatan.","advice":"Beri jarak 2 jam sebelum atau 4 jam sesudah antasida, sukralfat, kalsium, atau zink. Hindari juga minum doksisiklin bersama susu dalam jumlah besar. Nilai respons klinis dalam 48-72 jam."},{"a":"tetrasiklin","b":"warfarin","sev":"sedang","mech":"Penekanan flora usus penghasil vitamin K dan kemungkinan pergeseran ikatan protein.","efek":"INR meningkat dan risiko perdarahan bertambah, biasanya dalam 3-5 hari.","advice":"Periksa INR pada hari ke-3 sampai ke-5 terapi doksisiklin dan seminggu setelah antibiotik selesai. Turunkan dosis warfarin bila INR melewati batas target dan pantau tanda perdarahan."},{"a":"fkuinolon","b":"besi","sev":"sedang","mech":"Kelat antara ion besi dan gugus 4-okso serta karboksil fluorokuinolon.","efek":"Absorpsi siprofloksasin dan levofloksasin turun sampai 50-90% sehingga terapi gagal dan risiko resistensi naik.","advice":"Minum fluorokuinolon 2 jam sebelum atau 6 jam sesudah preparat besi, zink, atau multivitamin mineral. Untuk terapi TB resistan obat, jadwalkan suplemen pada waktu terpisah tetap dan catat di kartu minum obat."},{"a":"fkuinolon","b":"nsaid","sev":"sedang","mech":"Keduanya menurunkan ambang kejang melalui hambatan pengikatan GABA di reseptor GABA-A.","efek":"Agitasi, tremor, halusinasi, dan kejang, terutama pada lansia, gangguan ginjal, dan epilepsi.","advice":"Hindari kombinasi pada pasien epilepsi atau riwayat kejang; gunakan parasetamol sebagai analgesik. Bila dipakai, sesuaikan dosis kuinolon menurut eGFR dan hentikan segera bila muncul agitasi, mioklonus, atau bingung."},{"a":"fkuinolon","b":"kortikosteroid","sev":"mayor","mech":"Fluorokuinolon merusak matriks kolagen tendon sedangkan kortikosteroid menghambat perbaikannya.","efek":"Tendinitis dan ruptur tendon Achilles, dapat terjadi dalam 48 jam pertama sampai berbulan-bulan setelah terapi selesai.","advice":"Hindari kombinasi pada usia di atas 60 tahun, gangguan ginjal, dan penerima transplantasi. Pilih antibiotik lain bila memungkinkan. Bila dipakai, larang aktivitas fisik berat, dan hentikan kuinolon segera bila muncul nyeri tumit atau bengkak tendon."},{"a":"tiazid","b":"kalsium","sev":"sedang","mech":"Tiazid meningkatkan reabsorpsi kalsium di tubulus distal.","efek":"Hiperkalsemia dengan mual, konstipasi, poliuria, bingung, dan pada kasus berat batu ginjal atau aritmia; dapat membuka kedok hiperparatiroidisme.","advice":"Periksa kalsium serum sebelum dan 4-6 minggu setelah memulai tiazid pada pasien yang minum kalsium dan vitamin D. Batasi suplementasi kalsium sekitar 500-1000 mg/hari, dan bila kalsium melebihi 10,5 mg/dL hentikan suplemen serta periksa PTH."},{"a":"loop","b":"kortikosteroid","sev":"sedang","mech":"Pembuangan kalium di ginjal yang aditif melalui efek diuretik dan mineralokortikoid.","efek":"Hipokalemia dan hipomagnesemia yang memicu kram, kelemahan, aritmia, dan memperbesar risiko toksisitas digoksin.","advice":"Periksa kalium dan magnesium sebelum terapi lalu tiap 1-2 minggu selama steroid dosis tinggi. Pertahankan kalium di atas 3,5 mmol/L, beri suplemen KCl atau tambahkan spironolakton bila perlu, dan koreksi magnesium lebih dulu bila hipokalemia sulit diperbaiki."},{"a":"asetazolamid","b":"salisilat","sev":"mayor","mech":"Salisilat menggeser asetazolamid dari albumin dan menghambat sekresi tubularnya, sementara asidosis metabolik yang ditimbulkan asetazolamid meningkatkan masuknya salisilat ke otak.","efek":"Toksisitas salisilat dan asetazolamid: asidosis metabolik berat, letargi, tinitus, bingung, sampai koma; terutama pada lansia dan gangguan ginjal.","advice":"Hindari kombinasi terutama dengan asetosal dosis analgesik. Bila hanya asetosal 80 mg/hari, pantau bikarbonat serum dan status mental. Untuk glaukoma, pertimbangkan timolol atau latanoprost tetes sebagai pengganti asetazolamid oral."},{"a":"kortikosteroid","b":"insulin","sev":"sedang","mech":"Kortikosteroid meningkatkan resistensi insulin dan glukoneogenesis hati.","efek":"Hiperglikemia bermakna terutama siang dan sore hari; pada penghentian steroid mendadak justru terjadi hipoglikemia.","advice":"Naikkan dosis insulin secara antisipatif (sering perlu 20-50% lebih tinggi, terutama insulin prandial siang) saat steroid dosis tinggi dimulai. Periksa gula darah 4 kali sehari pada minggu pertama, dan turunkan kembali insulin secara bertahap seiring tapering steroid untuk mencegah hipoglikemia."},{"a":"acei","b":"nsaid","sev":"mayor","mech":"OAINS menghambat prostaglandin vasodilator arteriol aferen sementara penghambat ACE melebarkan arteriol eferen, sehingga tekanan filtrasi glomerulus jatuh.","efek":"Gagal ginjal akut, hiperkalemia, retensi natrium, dan hilangnya kendali tekanan darah; risiko memuncak bila ditambah diuretik (triple whammy) atau dehidrasi.","advice":"Hindari OAINS pada pasien ACE inhibitor, apalagi bila juga memakai diuretik. Gunakan parasetamol. Bila OAINS wajib, batasi maksimal 5-7 hari, periksa kreatinin dan kalium pada hari ke-3 sampai ke-7, dan hentikan sementara semuanya saat sakit dengan dehidrasi (sick day rules)."},{"a":"arb","b":"nsaid","sev":"mayor","mech":"Hambatan prostaglandin ginjal oleh OAINS ditambah blokade angiotensin II pada arteriol eferen.","efek":"Penurunan laju filtrasi glomerulus, gagal ginjal akut, hiperkalemia, dan tekanan darah tidak terkontrol.","advice":"Pilih parasetamol atau analgesik topikal. Bila OAINS harus diberikan, gunakan dosis terendah maksimal 5-7 hari, periksa kreatinin dan kalium dalam 3-7 hari, pastikan asupan cairan cukup, dan hentikan semuanya bila pasien muntah atau diare."},{"a":"diuretik","b":"nsaid","sev":"sedang","mech":"OAINS menahan natrium dan menurunkan aliran darah ginjal sehingga melawan efek diuretik.","efek":"Edema kembali, tekanan darah naik, dekompensasi gagal jantung, dan risiko gangguan ginjal akut bila digabung dengan penghambat sistem renin.","advice":"Hindari OAINS pada gagal jantung. Bila perlu, timbang berat badan harian (waspadai kenaikan lebih dari 2 kg dalam 3 hari), periksa kreatinin, kalium, dan natrium setelah 1 minggu, dan naikkan dosis diuretik hanya setelah OAINS dihentikan."},{"a":"acei","b":"kotrimoksazol","sev":"mayor","mech":"Trimetoprim memblok kanal natrium epitel di tubulus distal seperti amilorid sehingga ekskresi kalium terhambat, ditambah penurunan aldosteron oleh penghambat ACE.","efek":"Hiperkalemia berat dan aritmia; dilaporkan sebagai penyebab kematian mendadak pada lansia.","advice":"Pilih antibiotik lain (nitrofurantoin, sefaleksin, fosfomisin) untuk ISK pada pasien ACE inhibitor. Bila kotrimoksazol wajib, periksa kalium dan kreatinin sebelum terapi dan pada hari ke-3 sampai ke-5, hentikan bila kalium melebihi 5,5 mmol/L, dan hindari suplemen kalium."},{"a":"arb","b":"kotrimoksazol","sev":"mayor","mech":"Efek hemat kalium trimetoprim ditambah penurunan aldosteron akibat blokade reseptor angiotensin.","efek":"Hiperkalemia berat, kelemahan otot, bradikardia, dan aritmia ventrikel.","advice":"Ganti ke antibiotik non-kotrimoksazol bila memungkinkan. Bila tetap dipakai, periksa kalium dan kreatinin pada hari ke-3 sampai ke-5, batasi lama terapi, hentikan suplemen kalium dan pengganti garam berkalium, dan hentikan kotrimoksazol bila kalium melebihi 5,5 mmol/L."},{"a":"kotrimoksazol","b":"ksparing","sev":"mayor","mech":"Trimetoprim menghambat kanal natrium epitel sedangkan spironolakton dan eplerenon memblok reseptor mineralokortikoid; keduanya menahan kalium.","efek":"Hiperkalemia berat sampai henti jantung, terutama pada lansia dengan gagal jantung dan gangguan ginjal.","advice":"Hindari kombinasi. Untuk ISK pilih nitrofurantoin atau fosfomisin. Bila kotrimoksazol wajib, hentikan sementara spironolakton, periksa kalium dan kreatinin dalam 3 hari, dan rekam EKG bila kalium melebihi 6,0 mmol/L."},{"a":"kotrimoksazol","b":"azatioprin","sev":"mayor","mech":"Penekanan sumsum tulang aditif ditambah efek antifolat trimetoprim.","efek":"Leukopenia, trombositopenia, dan anemia megaloblastik, sampai sepsis neutropenik.","advice":"Bila kotrimoksazol dipakai sebagai profilaksis PCP pada pasien azatioprin, gunakan dosis profilaksis dan periksa darah lengkap tiap 2 minggu pada 2 bulan pertama lalu tiap bulan. Hentikan azatioprin bila leukosit di bawah 3.000/uL atau neutrofil di bawah 1.500/uL."},{"a":"kotrimoksazol","b":"sulfonilurea","sev":"mayor","mech":"Sulfametoksazol menghambat CYP2C9 sehingga metabolisme glimepirid terhambat, ditambah efek hipoglikemik intrinsik sulfonamid.","efek":"Hipoglikemia berat dan berkepanjangan, sering pada lansia dan gangguan ginjal.","advice":"Pertimbangkan menurunkan dosis glimepirid sekitar setengah selama terapi kotrimoksazol atau memilih antibiotik lain. Periksa gula darah mandiri 2-3 kali sehari selama terapi dan edukasi tanda hipoglikemia; sediakan glukosa oral."},{"a":"kotrimoksazol","b":"warfarin","sev":"mayor","mech":"Hambatan CYP2C9 terhadap S-warfarin, pergeseran ikatan albumin, dan penekanan flora usus penghasil vitamin K.","efek":"INR melonjak dalam 3-5 hari dan menimbulkan perdarahan mayor.","advice":"Pilih antibiotik lain bila memungkinkan. Bila kotrimoksazol wajib, turunkan dosis warfarin sekitar 25-50% sejak awal, periksa INR pada hari ke-3, ke-5, dan 1 minggu setelah antibiotik selesai, serta sediakan vitamin K bila INR melebihi 5."},{"a":"sglt2","b":"diuretik","sev":"sedang","mech":"Diuresis osmotik akibat glikosuria menambah efek natriuretik diuretik.","efek":"Deplesi volume, hipotensi ortostatik, pusing, dan gangguan ginjal akut prarenal, terutama pada lansia.","advice":"Pertimbangkan menurunkan dosis diuretik sekitar 25% saat memulai SGLT2 pada pasien euvolemik. Periksa tekanan darah berbaring dan berdiri serta kreatinin pada minggu ke-1 sampai ke-2. Penurunan eGFR awal sampai 10-15% bersifat sementara dan bukan alasan menghentikan obat."},{"a":"sglt2","b":"insulin","sev":"mayor","mech":"SGLT2 mendorong lipolisis dan ketogenesis; pengurangan dosis insulin yang berlebihan menghilangkan penekanan ketogenesis.","efek":"Ketoasidosis euglikemik dengan gula darah normal atau hanya sedikit naik sehingga sering terlambat dikenali, serta risiko hipoglikemia.","advice":"Jangan menurunkan insulin basal lebih dari 10-20% saat memulai SGLT2. Hentikan SGLT2 minimal 3 hari sebelum operasi, saat puasa lama, sakit berat, atau diet sangat rendah karbohidrat. Periksa keton (darah lebih baik daripada urin) pada setiap pasien dengan mual, muntah, atau sesak walau gula darah normal."},{"a":"sglt2","b":"sulfonilurea","sev":"sedang","mech":"Penurunan glukosa aditif melalui glikosuria dan sekresi insulin yang dipacu sulfonilurea.","efek":"Hipoglikemia, terutama pada lansia, gangguan ginjal, dan pasien yang makan tidak teratur.","advice":"Turunkan dosis glimepirid sekitar setengah saat memulai SGLT2 pada pasien dengan HbA1c mendekati target. Ajarkan pemantauan gula darah mandiri sebelum makan selama 2 minggu pertama dan sesuaikan lagi berdasarkan hasil."},{"a":"glp1","b":"insulin","sev":"mayor","mech":"Efek insulinotropik dan penekanan glukagon oleh agonis GLP-1 ditambah insulin eksogen, disertai perlambatan pengosongan lambung.","efek":"Hipoglikemia, terutama dengan insulin prandial, serta mual dan muntah yang memperbesar risiko dehidrasi.","advice":"Turunkan insulin prandial sekitar 20-25% saat memulai liraglutide dan pertahankan basal, lalu titrasi ulang. Periksa gula darah sebelum makan dan sebelum tidur selama 2 minggu. Titrasi liraglutide bertahap tiap minggu untuk mengurangi mual."},{"a":"dpp4","b":"acei","sev":"sedang","mech":"Penghambat DPP-4 mengurangi pemecahan substansi P dan bradikinin yang sudah menumpuk akibat penghambat ACE.","efek":"Peningkatan risiko angioedema, terutama pada bulan-bulan pertama terapi.","advice":"Kombinasi umumnya aman tetapi edukasi pasien mengenali bengkak bibir, lidah, atau wajah dan segera ke IGD. Bila terjadi angioedema, hentikan penghambat ACE selamanya dan ganti dengan ARB atau amlodipin; penghambat DPP-4 boleh dilanjutkan dengan hati-hati."},{"a":"pioglitazon","b":"insulin","sev":"mayor","mech":"Pioglitazon meningkatkan reabsorpsi natrium di tubulus kolektivus sementara insulin juga bersifat antinatriuretik.","efek":"Retensi cairan, edema tungkai, kenaikan berat badan, dan gagal jantung dekompensasi; juga hipoglikemia.","advice":"Jangan gunakan pioglitazon pada gagal jantung NYHA III-IV. Bila dikombinasi dengan insulin, batasi pioglitazon 15-30 mg/hari, timbang berat badan mingguan, dan hentikan bila naik lebih dari 2-3 kg disertai edema atau sesak. Turunkan insulin bila terjadi hipoglikemia berulang."},{"a":"statin","b":"fibrat","sev":"mayor","mech":"Gemfibrozil menghambat glukuronidasi dan transporter OATP1B1 statin sehingga kadarnya melonjak; keduanya juga miotoksik secara langsung.","efek":"Miopati dan rabdomiolisis dengan gagal ginjal akut; risiko jauh lebih tinggi dengan gemfibrozil daripada fenofibrat.","advice":"Jangan gabungkan gemfibrozil dengan statin apa pun. Bila terapi kombinasi untuk hipertrigliseridemia berat diperlukan, gunakan fenofibrat, batasi simvastatin maksimal 20 mg, periksa CK dan kreatinin sebelum dan 6-12 minggu setelahnya, dan hentikan bila CK melebihi 5 kali batas atas atau ada nyeri otot difus."},{"a":"statin","b":"amiodaron","sev":"mayor","mech":"Amiodaron menghambat CYP3A4 sehingga kadar simvastatin dan atorvastatin meningkat.","efek":"Mialgia, miopati, dan rabdomiolisis; risiko meningkat pada dosis simvastatin tinggi.","advice":"Batasi simvastatin maksimal 20 mg/hari bersama amiodaron dan atorvastatin maksimal 40 mg/hari, atau ganti ke rosuvastatin dosis rendah. Tanyakan nyeri otot tiap kunjungan, periksa CK bila ada keluhan, dan hentikan statin bila CK melebihi 5 kali batas atas."},{"a":"statin","b":"inducer","sev":"sedang","mech":"Rifampisin, karbamazepin, fenitoin, dan fenobarbital menginduksi CYP3A4 dan transporter OATP1B1.","efek":"Kadar statin turun bermakna sehingga LDL tidak mencapai target.","advice":"Periksa profil lipid 6-8 minggu setelah penginduksi dimulai; naikkan dosis statin atau ganti ke rosuvastatin yang lebih sedikit bergantung CYP3A4. Turunkan kembali dosis statin setelah penginduksi dihentikan untuk menghindari miopati."},{"a":"statin","b":"ccb-dhp","sev":"sedang","mech":"Amlodipin menghambat CYP3A4 secara sedang sehingga paparan simvastatin dan atorvastatin meningkat sekitar 1,5-2 kali.","efek":"Peningkatan risiko mialgia dan miopati.","advice":"Batasi simvastatin maksimal 20 mg/hari bila dikombinasi dengan amlodipin. Atorvastatin, rosuvastatin, dan pravastatin lebih aman. Tanyakan nyeri otot pada tiap kunjungan dan periksa CK bila ada keluhan."},{"a":"warfarin","b":"fibrat","sev":"mayor","mech":"Fibrat menggeser warfarin dari albumin dan menghambat CYP2C9.","efek":"INR naik tajam dalam 1-2 minggu dan menimbulkan perdarahan.","advice":"Turunkan dosis warfarin sekitar 20-30% saat fibrat dimulai, periksa INR pada hari ke-3 sampai ke-7 lalu tiap minggu sampai stabil dua kali berturut-turut. Ulangi pemantauan yang sama bila fibrat dihentikan."},{"a":"warfarin","b":"amiodaron","sev":"mayor","mech":"Amiodaron menghambat CYP2C9 dan CYP3A4; waktu paruhnya sangat panjang sehingga efeknya bertahan berminggu-minggu.","efek":"Efek warfarin meningkat sampai dua kali lipat, INR melonjak, dan terjadi perdarahan; efek muncul perlahan dalam 1-3 minggu dan menetap lama setelah amiodaron dihentikan.","advice":"Turunkan dosis warfarin sekitar 30-50% saat amiodaron dimulai. Periksa INR tiap 3-5 hari pada 2 minggu pertama lalu tiap minggu selama sebulan. Setelah amiodaron dihentikan, teruskan pemantauan INR selama minimal 2-3 bulan."},{"a":"warfarin","b":"tramadol","sev":"sedang","mech":"Hambatan CYP2D6 dan CYP3A4 serta kemungkinan pengaruh pada fungsi trombosit.","efek":"Kenaikan INR yang tidak terduga dan perdarahan, dilaporkan terutama pada awal terapi tramadol.","advice":"Gunakan parasetamol dosis biasa sebagai analgesik pilihan. Bila tramadol diperlukan, periksa INR dalam 3-5 hari setelah dimulai dan setelah dihentikan; sesuaikan dosis warfarin sesuai hasil."},{"a":"amiodaron","b":"bblocker","sev":"mayor","mech":"Depresi aditif pada nodus sinus dan nodus AV, diperberat hambatan metabolisme metoprolol oleh amiodaron.","efek":"Bradikardia berat, blok AV, henti sinus, dan hipotensi.","advice":"Kombinasi dipakai pada aritmia tetapi mulai dengan dosis penyekat beta rendah. Rekam EKG awal dan setelah 1-2 minggu, pertahankan denyut jantung di atas 50 kali/menit, dan hentikan atau turunkan dosis bila PR melebihi 240 ms atau muncul pusing dan sinkop. Waspada khusus pada lansia dan pasien tanpa pacu jantung."},{"a":"amiodaron","b":"nondhp","sev":"mayor","mech":"Hambatan nodus AV yang aditif ditambah efek inotropik negatif verapamil dan diltiazem.","efek":"Bradikardia simtomatik, blok AV derajat tinggi, asistol, dan perburukan gagal jantung.","advice":"Hindari kombinasi rutin; pilih penyekat beta bila perlu kendali laju tambahan. Bila terpaksa, rekam EKG serial, pantau denyut jantung dan tekanan darah, hentikan bila denyut di bawah 50 kali/menit atau muncul blok AV derajat dua ke atas."},{"a":"digoksin","b":"makrolid","sev":"mayor","mech":"Makrolid menghambat P-glikoprotein dan menekan flora usus pengurai digoksin (Eggerthella lenta).","efek":"Kadar digoksin naik sampai dua kali lipat dalam beberapa hari: mual, muntah, gangguan penglihatan warna, bradikardia, dan aritmia.","advice":"Ganti ke antibiotik non-makrolid bila memungkinkan. Bila klaritromisin atau eritromisin wajib, turunkan dosis digoksin sekitar setengah, periksa kadar digoksin pada hari ke-3 sampai ke-5 (target 0,5-0,9 ng/mL untuk gagal jantung), koreksi hipokalemia, dan rekam EKG bila ada keluhan."},{"a":"digoksin","b":"pengikat","sev":"minor","mech":"Antasida, sukralfat, dan adsorben mengikat digoksin di lumen usus sehingga absorpsinya berkurang.","efek":"Kadar digoksin sedikit menurun sehingga kendali laju atau gejala gagal jantung kurang optimal.","advice":"Beri jarak minimal 2 jam antara digoksin dan antasida, sukralfat, atau attapulgit. Bila kombinasi dipakai lama, periksa kadar digoksin setelah 1-2 minggu dan sesuaikan dosis bila perlu."},{"a":"ivabradin","b":"nondhp","sev":"kontra","mech":"Verapamil dan diltiazem menghambat CYP3A4 sehingga kadar ivabradin melonjak, ditambah efek penurun denyut jantung yang aditif.","efek":"Bradikardia berat, sinkop, dan perpanjangan QT.","advice":"Jangan dikombinasi. Untuk kendali laju tambahan pada pasien ivabradin, gunakan penyekat beta. Bila verapamil atau diltiazem harus dipakai, hentikan ivabradin dan pantau denyut jantung serta EKG."},{"a":"ccb-dhp","b":"makrolid","sev":"sedang","mech":"Klaritromisin dan eritromisin menghambat CYP3A4 sehingga kadar amlodipin, nifedipin, dan nikardipin meningkat.","efek":"Hipotensi, syok, dan gangguan ginjal akut; risiko tertinggi pada lansia dan pasien yang juga memakai diuretik.","advice":"Pilih azitromisin yang praktis tidak menghambat CYP3A4. Bila klaritromisin wajib, pertimbangkan menurunkan dosis amlodipin sementara, ukur tekanan darah harian selama terapi antibiotik, dan periksa kreatinin bila muncul pusing atau lemas."},{"a":"siklosporin","b":"azol","sev":"mayor","mech":"Flukonazol, itrakonazol, dan mikonazol gel oral menghambat CYP3A4 dan P-glikoprotein yang memetabolisme siklosporin.","efek":"Kadar siklosporin naik tajam sehingga terjadi nefrotoksisitas, hipertensi, tremor, dan neurotoksisitas.","advice":"Turunkan dosis siklosporin secara antisipatif (sering sampai separuh dengan itrakonazol), periksa kadar palung siklosporin dan kreatinin dalam 3-5 hari lalu tiap minggu, dan naikkan kembali dosis secara bertahap setelah azol dihentikan."},{"a":"siklosporin","b":"makrolid","sev":"mayor","mech":"Eritromisin dan klaritromisin menghambat CYP3A4 dan P-glikoprotein.","efek":"Kadar siklosporin melonjak dalam beberapa hari dan menimbulkan gagal ginjal akut, hipertensi, dan tremor.","advice":"Gunakan azitromisin atau antibiotik golongan lain. Bila tidak dapat dihindari, turunkan dosis siklosporin sekitar 50%, periksa kadar palung dan kreatinin pada hari ke-3, dan sesuaikan lagi setelah antibiotik selesai."},{"a":"siklosporin","b":"inducer","sev":"mayor","mech":"Rifampisin, karbamazepin, fenitoin, dan fenobarbital menginduksi CYP3A4 sehingga bersihan siklosporin meningkat drastis.","efek":"Kadar siklosporin anjlok dan terjadi penolakan cangkok atau kambuhnya penyakit autoimun.","advice":"Hindari rifampisin pada penerima transplantasi. Bila wajib, dosis siklosporin sering perlu dinaikkan dua sampai tiga kali dengan pemantauan kadar palung tiap 3-5 hari sampai stabil, lalu diturunkan bertahap saat penginduksi dihentikan agar tidak terjadi toksisitas."},{"a":"siklosporin","b":"ksparing","sev":"mayor","mech":"Siklosporin menekan aldosteron dan mengganggu ekskresi kalium tubulus distal, aditif dengan blokade reseptor mineralokortikoid.","efek":"Hiperkalemia berat dan aritmia, diperberat gangguan ginjal akibat siklosporin.","advice":"Hindari spironolakton dan eplerenon pada pasien siklosporin. Bila terpaksa, periksa kalium dan kreatinin tiap minggu pada bulan pertama, hentikan bila kalium melebihi 5,5 mmol/L, dan hindari pengganti garam berkalium."},{"a":"siklosporin","b":"nsaid","sev":"mayor","mech":"Vasokonstriksi arteriol aferen oleh siklosporin ditambah hilangnya prostaglandin vasodilator akibat OAINS.","efek":"Gagal ginjal akut, hipertensi, dan retensi cairan; kadar siklosporin juga dapat meningkat.","advice":"Gunakan parasetamol. Bila OAINS wajib, batasi 3-5 hari dengan dosis terendah, periksa kreatinin dan kadar siklosporin setelah 3 hari, dan pastikan hidrasi cukup. Hentikan segera bila kreatinin naik lebih dari 25% dari basal."},{"a":"siklosporin","b":"kolkisin","sev":"mayor","mech":"Siklosporin menghambat P-glikoprotein dan CYP3A4 yang mengeluarkan kolkisin.","efek":"Toksisitas kolkisin: miopati proksimal, neuropati, diare berat, dan mielosupresi, bahkan pada dosis kolkisin lazim.","advice":"Hindari kombinasi, terutama bila fungsi ginjal terganggu. Untuk serangan gout, gunakan kortikosteroid jangka pendek. Bila kolkisin wajib, batasi 0,5 mg/hari maksimal 3 hari, periksa CK dan darah lengkap, dan hentikan bila muncul kelemahan otot atau diare."},{"a":"pde5","b":"azol","sev":"sedang","mech":"Itrakonazol dan flukonazol menghambat CYP3A4 sehingga kadar sildenafil meningkat.","efek":"Hipotensi, sakit kepala berat, kemerahan wajah, hidung tersumbat, dan gangguan penglihatan.","advice":"Turunkan dosis sildenafil (mulai 25 mg dan jangan melebihi 25 mg dalam 48 jam bersama itrakonazol). Untuk pasien hipertensi paru yang memakai sildenafil rutin, pilih terbinafin atau antijamur non-azol dan pantau tekanan darah."},{"a":"bblocker","b":"simpatomimetik","sev":"sedang","mech":"Blokade reseptor beta menyisakan stimulasi alfa pseudoefedrin tanpa lawan (unopposed alpha).","efek":"Kenaikan tekanan darah, bradikardia refleks, dan sakit kepala; kendali hipertensi menjadi buruk.","advice":"Hindari dekongestan oral pada pasien hipertensi yang memakai penyekat beta; gunakan salin semprot hidung, kortikosteroid nasal, atau antihistamin tanpa pseudoefedrin. Bila terpaksa, batasi maksimal 3 hari dan ukur tekanan darah harian."},{"a":"traneksamat","b":"coc","sev":"mayor","mech":"Efek protrombotik aditif: estrogen meningkatkan faktor pembekuan sementara asam traneksamat menghambat fibrinolisis.","efek":"Peningkatan risiko trombosis vena dalam, emboli paru, dan trombosis arteri.","advice":"Hindari kombinasi, terutama pada perokok, usia di atas 35 tahun, obesitas, imobilisasi, atau riwayat tromboemboli. Untuk menoragia pada pengguna pil kombinasi, gunakan OAINS atau naikkan pengendalian hormonal. Bila asam traneksamat tetap dipakai, batasi 5 hari saat menstruasi dan edukasi tanda trombosis tungkai."}];
